// 递归消括号（仅理解，超时风险）
class Solution {
    public boolean isValid(String s) {
        String t = s.replace("()", "").replace("[]", "").replace("{}", "");
        if (t.equals(s)) return s.isEmpty();   // 没消掉任何东西
        return isValid(t);
    }
}

// 最优解：栈，O(n) 时间、O(n) 空间
class Solution {
    public boolean isValid(String s) {
        if (s.length() % 2 == 1) return false;          // 剪枝：奇数长度必无效
        Map<Character, Character> pair = Map.of(')', '(', ']', '[', '}', '{');
        Deque<Character> stack = new ArrayDeque<>();
        for (char c : s.toCharArray()) {
            if (!pair.containsKey(c)) {                  // 左括号
                stack.push(c);
            } else {                                     // 右括号
                if (stack.isEmpty() || stack.pop() != pair.get(c)) {
                    return false;                        // 空栈 or 不匹配
                }
            }
        }
        return stack.isEmpty();                         // 必须全部匹配完
    }
}

