class Solution {
    public int removeElement(int[] nums, int val) {
        int n = nums.length;
        int[] temp = new int[n];
        int k = 0;
        for (int i = 0; i < n; i++) {
            if (nums[i] != val) {
                temp[k++] = nums[i];
            }
        }
        // 拷回原数组
        for (int i = 0; i < k; i++) {
            nums[i] = temp[i];
        }
        return k;
    }
}

class Solution {
    public int removeElement(int[] nums, int val) {
        int slow = 0;
        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != val) {
                nums[slow] = nums[fast]; // 保留这个元素
                slow++;
            }
            // 等于 val 时：fast 前进，slow 不动，等于跳过
        }
        return slow; // slow 的值恰好等于非 val 元素的个数
    }
}

class Solution {
    public int removeElement(int[] nums, int val) {
        int left = 0;
        int right = nums.length - 1;
        while (left <= right) {
            if (nums[left] == val) {
                // 用末尾元素替换当前 val，right 左移
                // left 不前进——换过来的元素可能也是 val，需要下一轮再判断
                nums[left] = nums[right];
                right--;
            } else {
                // 当前元素不是 val，正常前进
                left++;
            }
        }
        // left 指向第一个「非法位置」，恰好等于保留元素个数
        return left;
    }
}

