class Solution {
    public int strStr(String haystack, String needle) {
        int n = haystack.length(), m = needle.length();
        for (int i = 0; i <= n - m; i++) {       // 起点枚举，i+m-1 <= n-1
            int j = 0;
            while (j < m && haystack.charAt(i + j) == needle.charAt(j)) j++;
            if (j == m) return i;                // 整段匹配
        }
        return -1;
    }
}

class Solution {
    public int strStr(String haystack, String needle) {
        int n = haystack.length(), m = needle.length();
        if (m == 0) return 0;                      // 题目保证 m>=1，但稳妥处理
        // 1) 求 next 数组（前缀函数）
        int[] next = new int[m];
        for (int i = 1, j = 0; i < m; ) {
            if (needle.charAt(i) == needle.charAt(j)) {
                next[i++] = ++j;                   // 匹配成功，长度 +1
            } else if (j > 0) {
                j = next[j - 1];                   // 失配，跳到更短重叠前缀
            } else {
                next[i++] = 0;                     // j==0 仍失配，next[i]=0
            }
        }
        // 2) 在 haystack 上匹配
        for (int i = 0, j = 0; i < n; ) {
            if (haystack.charAt(i) == needle.charAt(j)) {
                i++; j++;
                if (j == m) return i - m;          // 命中，返回起点
            } else if (j > 0) {
                j = next[j - 1];                   // 失配，利用 next 跳过已匹配部分
            } else {
                i++;                               // j==0 失配，主串前进
            }
        }
        return -1;
    }
}

