class Solution {
    public boolean isValidSudoku(char[][] board) {
        // 校验每一行
        for (int i = 0; i < 9; i++) {
            Set<Character> set = new HashSet<>();
            for (int j = 0; j < 9; j++) {
                char c = board[i][j];
                if (c == '.') continue;
                if (!set.add(c)) return false;
            }
        }
        // 校验每一列
        for (int j = 0; j < 9; j++) {
            Set<Character> set = new HashSet<>();
            for (int i = 0; i < 9; i++) {
                char c = board[i][j];
                if (c == '.') continue;
                if (!set.add(c)) return false;
            }
        }
        // 校验每个 3x3 宫
        for (int bi = 0; bi < 3; bi++) {
            for (int bj = 0; bj < 3; bj++) {
                Set<Character> set = new HashSet<>();
                for (int i = bi * 3; i < bi * 3 + 3; i++) {
                    for (int j = bj * 3; j < bj * 3 + 3; j++) {
                        char c = board[i][j];
                        if (c == '.') continue;
                        if (!set.add(c)) return false;
                    }
                }
            }
        }
        return true;
    }
}

class Solution {
    public boolean isValidSudoku(char[][] board) {
        boolean[][] rows = new boolean[9][10];
        boolean[][] cols = new boolean[9][10];
        boolean[][] boxes = new boolean[9][10];

        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                char c = board[i][j];
                if (c == '.') continue;
                int num = c - '0';
                int box = (i / 3) * 3 + (j / 3);
                if (rows[i][num] || cols[j][num] || boxes[box][num]) {
                    return false;
                }
                rows[i][num] = true;
                cols[j][num] = true;
                boxes[box][num] = true;
            }
        }
        return true;
    }
}

class Solution {
    public boolean isValidSudoku(char[][] board) {
        int[] row = new int[9], col = new int[9], box = new int[9];
        for (int i = 0; i < 9; i++) {
            for (int j = 0; j < 9; j++) {
                if (board[i][j] == '.') continue;
                int num = board[i][j] - '1';   // 0-based
                int b = (i / 3) * 3 + (j / 3);
                int bit = 1 << num;
                if ((row[i] & bit) != 0 || (col[j] & bit) != 0 || (box[b] & bit) != 0) {
                    return false;
                }
                row[i] |= bit; col[j] |= bit; box[b] |= bit;
            }
        }
        return true;
    }
}

